export interface NewsVocab {
    word: string;
    pos: string;   // adj / n / v ...
    en: string;    // 紙面用: 短い英英語釈 (日本語なし)
    ja: string;    // 解説シート用: 日本語訳
}

export interface SyntaxNote {
    en: string;    // 本文からの一文
    point: string; // 文法ポイント (日本語ラベル)
    ja: string;    // 日本語の構文解説
    /** 一言一句 (No.57 の一部が持っている)。いま解説シートには出ていない */
    chunks?: GlossChunk[];
}

// 紙面の一文につける注釈。画面で文をタップすると出る (印刷には出ない)。
// No.61 (2026-09-07) から。難しいのは単語ではなく構造なので、訳だけでなく
// 「日本語話者がなぜここで転ぶか」を必ず書く。
// 一文から抜き出して、その場でトレーニングに登録できる表現。
// 粒度は2段構える: 語や連語 (at source) と、意味のまとまり (all deducted at source)。
export interface GlossPick {
    en: string;                 // 登録する表現
    ja: string;                 // 日本語
    kind?: 'word' | 'phrase';   // 'word' は /api/user-words、既定の 'phrase' は /api/phrases
}

// 一文を頭から順に切って、切れ端ごとに日本語を当てる欄。
// No.75 (2026-09-21) から。訳を1本置くだけだと「全体の意味は分かるが、
// どの語がどこに効いているか分からない」で終わる。英語の語順のまま前から読めるように、
// 意味のかたまり (3〜7語) で割って並べる。
//   - en を頭から順につなぐと元の一文に戻ること (語を落とさない・入れ替えない)
//   - ja は直訳寄り。日本語として整えるより、その切れ端が何をしているかを優先する
//   - 主語・動詞の切れ端には「← ここが主語」のような一言を足してよい
export interface GlossChunk {
    en: string;
    ja: string;
}

export interface SentenceGloss {
    en: string;         // 紙面の一文。splitSentences() が返す形と一字一句そろえること
    ja: string;         // 日本語訳
    why: string;        // なぜ日本人に難しいか (構造の理由。単語の意味だけ書かない)
    chunks?: GlossChunk[]; // 一言一句。頭から順に切って日本語を当てたもの (任意)
    skeleton?: string;  // 文の骨格 (任意)
    picks?: GlossPick[]; // その文から登録する価値のある表現
    // 文が長すぎてカードにならないとき、代わりに登録する短い形。
    // 60語の一文をそのままカードにしても復習できないので、核だけ切り出す。
    core?: string;
}

export interface NewsArticle {
    kicker: string;         // セクションラベル
    headline: string;
    standfirst?: string;    // デック (小見出し)
    byline?: string;
    body: string[];         // 段落
}

export interface StatLine {
    label: string;
    value: string;
}

// その号の素材 (前日に聴いた回)。紙面の日付欄の下に出典として刷る。
export interface EditionSource {
    slot: 'podcast' | 'interview';
    show: string;    // 'JRE Clips' / 'Vanity Fair' ...
    date: string;    // 素材の日付 (YYYY-MM-DD)
    title: string;   // 回のタイトル
    url?: string;    // 元動画
}

export interface NewspaperEdition {
    date: string;           // YYYY-MM-DD
    editionNo: number;
    weekdayLong: string;    // Thursday, July 9, 2026
    // --- 号外 (EXTRA) 用の任意フィールド。通常号は未指定でこれまで通り。---
    id?: string;            // 号外の一意キー (日次号は date がキー)。EXTRA_EDITIONS 用。
    extra?: boolean;        // 号外フラグ (バッジ表示を「号外」に)
    theme?: 'aot' | 'ghost'; // 見た目テーマ。'aot'=進撃号 / 'ghost'=機械の中の幽霊号
    mastheadTitle?: string; // マストヘッド見出し上書き (既定 "The Tonio Times")
    mastheadTagline?: string; // マストヘッド下のタグライン上書き
    mastheadKicker?: string;  // 号数の代わりに出す文字列 (例 "号外 · EXTRA")
    motto: string;          // ラテン語の標語 + 訳
    // weather は廃止 (2026-09-07)。実在しない天気を刷る欄だったので紙面から外した。
    quote: { text: string; source: string };
    // 素材の記録 (No.54まで)。No.55〜は紙面に出典を刷らないので指定しない。
    sources?: EditionSource[];
    lead: NewsArticle;
    rail: NewsArticle;
    railStats: StatLine[];
    // 会話のお手本。自然な話し言葉を読むだけでスピーキングの型が入る。
    voices: {
        kicker: string;
        headline: string;
        standfirst: string;
        turns: { q: string; a: string }[];
    };
    story: NewsArticle & { cast: string };
    // No.55〜は語彙の解説をやめたので、以下3つは任意 (No.54までの号は持っている)。
    vocab?: NewsVocab[];
    // 話すために: 紙面の生きた言い回し + 会話での使い方 (解説シート/日本語)
    sayIt?: { phrase: string; ja: string }[];
    // 書くために: 構文を「真似できる型」として解説 (解説シート/日本語)
    syntax?: SyntaxNote[];
    // 文をタップすると出る注釈 (画面のみ)。難所のある文だけ入れればよく、
    // 入っている文には点線が付いて「ここが難所だ」と分かるようになっている。
    glosses?: SentenceGloss[];
    // とにおへの一言。日本語なので英字紙面ではなく解説シート(Sheet 2)に刷る。
    // quote も同じく Sheet 2 の編集後記に添える (2026-08-04 移設)。
    editorsNote: string;
}

