// 公開済みの号外を新しい順で返す (未来日付は隠す)。
export function getPublishedExtras(): NewspaperEdition[] {
    const cutoff = publishCutoff();
    return EXTRA_EDITIONS
        .filter((e) => e.date <= cutoff)
        .sort((a, b) => b.date.localeCompare(a.date));
}

// ドリップ公開: 未来日付の号は「その日」まで隠す (journal のドリップと同じ思想)。
// DRIP_ENABLED=false で全号即時公開 (未来日付もカレンダー/紙面に出す)。
// 2026-07-14 ユーザー指示で解禁 (No.7〜18 を即時表示)。再びドリップに戻すなら true。
const DRIP_ENABLED = false;

function localTodayStr(): string {
    const d = new Date();
    const p = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// 公開判定の基準日。ドリップ有効なら今日、無効なら遠い未来 (=全号公開)。
function publishCutoff(): string {
    return DRIP_ENABLED ? localTodayStr() : '9999-12-31';
}

// 最新号 (公開済みのうち date 降順の先頭)
export function getLatestEdition(): NewspaperEdition {
    const cutoff = publishCutoff();
    const keys = Object.keys(EDITIONS).filter((k) => k <= cutoff).sort((a, b) => b.localeCompare(a));
    if (keys.length === 0) {
        // まだ1号も公開日が来ていない保険: 全体の最古を返す
        const all = Object.keys(EDITIONS).sort((a, b) => a.localeCompare(b));
        return EDITIONS[all[0]];
    }
    return EDITIONS[keys[0]];
}

// 開いた瞬間に出す号。書き溜めで未来号が入っているので「最新号」だと月末が出てしまう。
// 今日の号、無ければ今日以前で最も新しい号を返す (どちらも無ければ最古の号)。
export function getTodaysEdition(): NewspaperEdition {
    const today = localTodayStr();
    const cutoff = publishCutoff();
    const limit = today < cutoff ? today : cutoff;
    const keys = Object.keys(EDITIONS).filter((k) => k <= limit).sort((a, b) => b.localeCompare(a));
    if (keys.length === 0) return getLatestEdition();
    return EDITIONS[keys[0]];
}

export function getEdition(date: string): NewspaperEdition | undefined {
    if (date > publishCutoff()) return undefined; // 未公開号 (ドリップ時のみ効く)
    return EDITIONS[date];
}

// 公開済みの全号を date 降順で返す (カレンダー/一覧用)。ドリップ無効時は未来号も含む。
export function getAllEditions(): NewspaperEdition[] {
    const cutoff = publishCutoff();
    return Object.keys(EDITIONS)
        .filter((k) => k <= cutoff)
        .sort((a, b) => b.localeCompare(a))
        .map((k) => EDITIONS[k]);
}

// ===================== 読む前の単語リスト =====================
// 号の中の picks (文タップで出るやつ) を、紙面の並び順のまま section ごとに集めて返す。
// 「読んでから分からない語を拾う」のではなく「先に語を通してから読む」ための材料。
// 同じ語が何度も出る号があるので、en の小文字で重複を落とす (最初に出たほうを残す)。

export type PickSection = 'lead' | 'rail' | 'voices' | 'story';

export interface EditionPickGroup {
    section: PickSection;
    label: string;       // 画面に出す日本語の欄名
    sentences: number;   // その欄の注釈つきの文の数
    picks: GlossPick[];
}

const SECTION_LABEL: Record<PickSection, string> = {
    lead: '1面 — THE LONG VIEW',
    rail: '2本目 — 読み物',
    voices: 'VOICES — 町の声',
    story: 'FICTION — 小説',
};

// 文がどの欄のものかを、欄の本文を突き合わせて決める。
// 照合は英数字だけに潰す (引用符やダッシュの揺れで外れないように)。
const flat = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '');

export function collectEditionPicks(ed: NewspaperEdition): EditionPickGroup[] {
    const glosses = ed.glosses ?? [];
    if (!glosses.length) return [];

    const zones: { section: PickSection; text: string }[] = [
        { section: 'lead', text: flat([ed.lead.headline, ed.lead.standfirst ?? '', ...ed.lead.body].join(' ')) },
        { section: 'rail', text: flat([ed.rail.headline, ed.rail.standfirst ?? '', ...ed.rail.body].join(' ')) },
        { section: 'voices', text: flat([ed.voices.headline, ed.voices.standfirst, ...ed.voices.turns.flatMap((t) => [t.q, t.a])].join(' ')) },
        { section: 'story', text: flat([ed.story.headline, ...ed.story.body].join(' ')) },
    ];

    const groups = new Map<PickSection, EditionPickGroup>();
    const seen = new Set<string>();   // 号全体での重複落とし

    for (const g of glosses) {
        const key = flat(g.en);
        const zone = zones.find((z) => key.length > 0 && z.text.includes(key));
        const section: PickSection = zone ? zone.section : 'lead';
        let grp = groups.get(section);
        if (!grp) {
            grp = { section, label: SECTION_LABEL[section], sentences: 0, picks: [] };
            groups.set(section, grp);
        }
        grp.sentences += 1;
        for (const p of g.picks ?? []) {
            const k = p.en.trim().toLowerCase();
            if (seen.has(k)) continue;
            seen.add(k);
            grp.picks.push(p);
        }
    }

    const order: PickSection[] = ['lead', 'rail', 'voices', 'story'];
    return order.filter((s) => groups.has(s)).map((s) => groups.get(s)!);
}
